SELECT ROUND(
  100.0 * SUM(CASE WHEN p.Admission IS NOT NULL AND TRIM(p.Admission) <> '' THEN 1 ELSE 0 END) / COUNT(DISTINCT p.ID), 2
) AS inpatient_percentage
FROM Patient p
JOIN Laboratory l ON p.ID = l.ID
WHERE p.Birthday BETWEEN '1930-01-01' AND '1940-12-31';

SELECT MAX(CAST(RNP AS FLOAT)) AS Max_RNP
FROM Laboratory
WHERE RNP IS NOT NULL;

SELECT ROUND(100.0 * SUM(CASE WHEN Birthday >= '1960-01-01' THEN 1 ELSE 0 END) / COUNT(*), 1) AS percent_born_1960_or_later
FROM Patient
WHERE Diagnosis = 'psoriatic arthritis';

